import { AppHeader } from '../../slots/defs/appHeader';
import { useCurrentSheet } from '../../session/session';
import { STATUSES, statusCount, useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { useSheetDueTotal } from '../rates/due.slot';
import { useSheetOverdue } from '../overdue/overdue.slot';

// The sheet's counters, always in the header: its people (retired people included), its claims per
// status (the summary's counts) and its due- and overdue-totals (the rollup's), from the same figures.
function HeaderCounters() {
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const due = useSheetDueTotal();
  const overdue = useSheetOverdue();

  return (
    <p data-testid="header-counters">
      People <strong data-testid="header-people-count">{(people.data ?? []).length}</strong>{' '}
      {STATUSES.map((s) => (
        <span key={s}>
          {s} <strong data-testid={`header-claims-${s}-count`}>{statusCount(claims.data, s)}</strong>{' '}
        </span>
      ))}
      Due total <strong data-testid="header-due-total">{due}</strong>{' '}
      Overdue total <strong data-testid="header-overdue-total">{overdue.total}</strong>
    </p>
  );
}

export const contribution = AppHeader.fill({ order: 30, Component: HeaderCounters });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { AppHeader } from '../../slots/defs/appHeader';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { useSettings } from '../settings/settings';
import { type Sheet, sheetKey, useSheet } from './sheet';

function SheetToday() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const loaded = useSheet(sheet);
  const settings = useSettings(sheet);
  const [input, setInput] = useState('');
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (today: string) =>
      postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}/today`, { today, user }),
    // A new today changes every date decision on the sheet: re-read all of it.
    onSuccess: () => queryClient.invalidateQueries({ queryKey: sheetKey(sheet) }),
  });
  const submit = useSubmitOnce(save);
  const archive = useMutation({
    mutationFn: () => postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}/archive`, { user }),
    onSuccess: (archived) => queryClient.setQueryData(sheetKey(sheet), archived),
  });
  const submitArchive = useSubmitOnce(archive);
  // The sheet's one error element: a refused today or a refused archive, whichever was tried last.
  const failed = save.isError ? save.error : archive.isError ? archive.error : null;

  if (!user || !loaded.data) return null;
  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        archive.reset();
        submit(input.trim());
      }}
    >
      Today <strong data-testid="sheet-today">{loaded.data.today}</strong>{' '}
      <input
        data-testid="sheet-today-input"
        type="date"
        value={input}
        onChange={(e) => {
          setInput(e.target.value);
          save.reset();
          archive.reset();
        }}
      />
      <button type="submit" data-testid="sheet-today-save">
        Set today
      </button>
      {' '}Parent <strong data-testid="sheet-parent">{settings.data?.parent ?? ''}</strong>
      {' '}Archived <strong data-testid="sheet-archived">{loaded.data.archived ? 'yes' : 'no'}</strong>{' '}
      <button
        type="button"
        data-testid="sheet-archive"
        onClick={() => {
          save.reset();
          submitArchive();
        }}
      >
        Archive sheet
      </button>
      {failed && (
        <span data-testid="sheet-error" role="alert">
          {' '}{failed instanceof HttpError && failed.reason ? failed.reason : 'Not a valid date.'}
        </span>
      )}
    </form>
  );
}

export const contribution = AppHeader.fill({ order: 20, Component: SheetToday });
