import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useAsOf } from '../../session/session';

/** `today` (yyyy-MM-dd) is the sheet's own date: every date decision and default uses it, never the clock.
 *  An `archived` sheet stays visible but the server refuses every change to it. `asOf` (yyyy-MM-dd) is the
 *  date this screen shows the sheet as of, null when it shows it as it is now; `archived` is then as it
 *  stood at the end of that date. */
export type Sheet = { id: string; today: string; archived: boolean; asOf: string | null };

/** Every per-sheet query key starts with ['sheet', id], so loading a sheet re-reads all of it. */
export const sheetKey = (id: string) => ['sheet', id] as const;

/** A per-sheet query key as read for the screen's as-of date: the key itself when there is none, so a
 *  change made (never while one is set) updates the very queries it read. */
export const asOfKey = <K extends readonly unknown[]>(key: K, asOf: string) =>
  (asOf === '' ? key : [...key, { asOf }]) as unknown as K;

/** A read path with the screen's as-of date added (as `asOf`), so the server answers as it stood then. */
export const asOfPath = (path: string, asOf: string) =>
  asOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;

export function useSheet(id: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(sheetKey(id), asOf),
    queryFn: () => getJson<Sheet>(asOfPath(`/api/sheets/${encodeURIComponent(id)}`, asOf)),
    enabled: id !== '',
  });
}

/** The sheet's today (yyyy-MM-dd), or undefined while the sheet loads. Use it for every default date.
 *  While the screen shows the sheet as of a date, that date stands in for it in every figure. */
export function useSheetToday(id: string): string | undefined {
  const data = useSheet(id).data;
  return data?.asOf ?? data?.today;
}
import { useMutationState, useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** `version` moves on with each stored edit; an edit is saved only over the version its editor loaded.
 *  `statementCount` is how many statements were taken of them; `statedTotal` (two decimals, or n/a)
 *  and `statementDate` (yyyy-MM-dd) are the last one's, null when none was taken. `retired` is set
 *  as soon as a `retiredFrom` date (yyyy-MM-dd, null when not retired) is, whatever the date;
 *  `retiredNow` once the sheet's today reaches it: from then their OPEN claims count in no live total
 *  unless a statement bound them, as a hold's would.
 *  `holds` are their holds, oldest first; `held` whether they have any. Their OPEN claims dated within
 *  a hold count in no live total unless a statement bound them; their SETTLED ones still do.
 *  `patronIds` are the ids of the other people on the sheet they named as their patrons, in the order they named them.
 *  `grade` is the grade in force on the sheet's today; `grades` every grade with the date it applies from.
 *  `terms` are their own terms in whole days (null when none), ahead of their grade's and the sheet's.
 *  `contact` is their contact (trimmed, lower-cased; null when none), no other person's on the sheet.
 *  `aliases` are other names they are found by (no name or other alias on the sheet), sorted as names are compared. */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: Grades;
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  retiredNow: boolean;
  held: boolean;
  holds: Hold[];
  patronIds: number[];
  terms: number | null;
  contact: string | null;
  aliases: string[];
};

/** A hold from its from-date to its to-date (yyyy-MM-dd, both inclusive; null for no end). */
export type Hold = { from: string; to: string | null };

/** Whether the hold covers the date (yyyy-MM-dd). */
export const covers = (h: Hold, date: string) => h.from <= date && (h.to === null || date <= h.to);

export const GRADES = ['A', 'B', 'C'] as const;

/** A person's grades, each with the date (yyyy-MM-dd) it applies from; the first has none (null),
 *  applying from the beginning of time. */
export type Grades = { grade: string; from: string | null }[];

/** The grade in force on the date (yyyy-MM-dd): the one with the latest from-date on or before it. */
export function gradeOn(grades: Grades, on: string | undefined): string {
  let best = grades[0];
  for (const g of grades) {
    if (g.from === null || (on !== undefined && g.from <= on)) {
      if ((best.from ?? '') <= (g.from ?? '')) best = g;
    }
  }
  return best?.grade ?? 'A';
}

/** Under the sheet's key, so loading the sheet again re-reads its people. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;

export function usePeople(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(peopleKey(sheet), asOf),
    queryFn: () => getJson<Person[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/people`, asOf)),
    enabled: sheet !== '',
  });
}

/** The id of the person whose editor is open in the person form ('' when it adds). */
export const useEditingPerson = () => useSearchParam('editPerson', asString);

/** Whether the people list shows retired people too; off when the screen is first opened. */
export const useShowRetired = () => useSearchParam('showRetired', asFlag);

/** The mutation key of an action on a person's row (a statement, a hold, a retirement): the row
 *  shows only the error of the latest one taken, so taking the next action clears an earlier one's. */
export const personActionKey = (sheet: string, personId: number) => [...peopleKey(sheet), personId, 'action'] as const;

/** When the latest action on the person's row was taken (0 when none was). */
export function useLatestPersonAction(sheet: string, personId: number): number {
  const taken = useMutationState({
    filters: { mutationKey: personActionKey(sheet, personId) },
    select: (m) => m.state.submittedAt,
  });
  return Math.max(0, ...taken);
}

/** The ids of the people selected for a bulk grade, kept in the URL (`selectedPeople`, comma separated). */
export function useSelectedPeople(): [number[], (ids: number[]) => void] {
  const [raw, setRaw] = useSearchParam('selectedPeople', asString);
  const ids = raw.split(',').filter((s) => s !== '').map(Number).filter((n) => !Number.isNaN(n));
  return [ids, (next) => setRaw(next.join(','))];
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** The sheet's settings: `clerkLimit` (two decimals) is the most due a clerk may settle a claim at,
 *  null for no limit; `floor` (two decimals) is the least a claim's live due may be; `terms` is the
 *  business days after its date a claim is due by; `latePct` (two decimals) is the percent of an overdue
 *  claim's figure plus its earlier charges (compounding) charged at each full 30 days it is overdue (the one in force on that boundary); `policyDate` (yyyy-MM-dd) is the date
 *  rounding turns on, null when blank (then the sheet's today); `periodNumberingFrom` (yyyy-MM-dd) is the
 *  date from which claims opened are numbered per period, null when blank (off); `gradeTerms` is the terms
 *  in force for each grade (its own, else the sheet's), by grade; `cap` (two decimals) is the most a person's
 *  due-total may be, null for no cap; `proofThreshold` (two decimals) is the due above which a claim needs a proof
 *  before it is settled or approved, null for none; `noteThreshold` (two decimals) is the due above which a
 *  claim needs a note before it is opened, null for none. Each of these that carries a figure is the one in force on the sheet's today.
 *  `floorFrom` and `latePctFrom` are the floor and late percent recorded, oldest from-date (yyyy-MM-dd) first:
 *  a claim's floor and late percent are those in force on its date. `perms` is the permission matrix: the roles
 *  that may take each action (open, settle, void, reassign, close, reopen), comma separated, by action; null when
 *  blank (the standing rule). `graceDays` is the whole days after its to-date an open period is closed when the
 *  sheet's today moves, null when blank (off). `entryDate` (yyyy-MM-dd) is the default date of a new claim
 *  in place of the sheet's today, null when blank (off). `gradeGrace` is each grade's grace days in force on the sheet's
 *  today, by grade, null when it has none; `gradeGraceFrom` is each grade's grace days recorded, by grade, oldest
 *  from-date first: a claim's grace is the one in force on its date for its person's grade then. `gradeProofThreshold`
 *  is each grade's proof threshold in force on the sheet's today, by grade, null when it has none (then the sheet's).
 *  `pot` (two decimals) is the sum a balanced pool shares out among its members, null for none; it is not dated.
 *  `parent` is the id of the sheet whose rates a grade with no rate in force on a date takes (then its parent's, up
 *  to three levels up), null for none; it is not dated. */
export type Settings = { clerkLimit: string | null; floor: string; terms: string; latePct: string; policyDate: string | null;
  periodNumberingFrom: string | null; gradeTerms: Record<string, string>; cap: string | null; proofThreshold: string | null;
  floorFrom: Dated[]; latePctFrom: Dated[]; perms: Record<string, string | null>;
  graceDays: string | null; noteThreshold: string | null; entryDate: string | null;
  gradeGrace: Record<string, string | null>; gradeGraceFrom: Record<string, Dated[]>;
  gradeProofThreshold: Record<string, string | null>; pot: string | null; parent: string | null };

/** A setting's value recorded from a date (yyyy-MM-dd); a null value is blank. */
export type Dated = { from: string; value: string | null };

/** The floor a sheet has before any is recorded. */
const STARTING_FLOOR = '1.00';

/** The late percent a sheet has before any is recorded. */
const STARTING_LATE_PCT = '0.00';

/** The value in force on the date: the one with the latest from-date on or before it, else `starting`. */
export function valueOn(history: Dated[], date: string, starting: string): string {
  let found: string | null = null;
  for (const d of history) if (d.from <= date) found = d.value;
  return found ?? starting;
}

/** The floor in force on each date; undefined until the settings are read. */
export function floorOf(settings: Settings | undefined): ((date: string) => string) | undefined {
  return settings && ((date) => valueOn(settings.floorFrom, date, STARTING_FLOOR));
}

/** The late percent in force on each date; undefined until the settings are read. */
export function latePctOf(settings: Settings | undefined): ((date: string) => string) | undefined {
